       cursor: pointer;
       transition: transform 0.18s ease, box-shadow 0.18s ease, filter 0.18s ease;
     }

     button:hover {
       transform: translateY(-1px);
       box-shadow: 0 16px 32px rgba(124, 58, 237, 0.42);
       filter: brightness(1.04);
     }

     button:active {
       transform: translateY(0);
     }

     .status {
       min-height: 1.25rem;
       margin: 0;
       font-size: 0.95rem;
       color: var(--success);
     }
   </style>
 </head>
 <body>
   <main class="card">
     <h1>Terms Consent</h1>
     <p>Please confirm your agreement before submitting the form.</p>

     <form id="consent-form">
       <div class="form-field">
         <div class="checkbox-row">
           <input id="terms" name="terms" type="checkbox" required>
           <label for="terms">I agree to the terms of use.</label>
         </div>
         <p class="helper-text">Required to continue.</p>
       </div>

